using System;
using System.IO;
using System.Linq;
using Unity.FPS.Game;
using Unity.FPS.Gameplay;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEditor.TestTools.TestRunner.Api;
using UnityEngine;
using UnityEngine.SceneManagement;
using Object=UnityEngine.Object;
namespace IronRequiem.Editor
{
    [InitializeOnLoad] public static class PrimaryModuleAuthoring
    {
        public const string Lab="Assets/IronRequiem/Scenes/PrimaryModuleLab.unity",Player="Assets/IronRequiem/Prefabs/Player/Player_PrimaryModule_v02.prefab",Weapon="Assets/IronRequiem/Prefabs/Weapons/Weapon_IR_PrimaryModule_v02.prefab",Projectile="Assets/IronRequiem/Prefabs/Weapons/Projectile_IR_PrimaryModule_v02.prefab",Art="Assets/IronRequiem/Art/Weapons/PrimaryModuleV02",Reports="Tools/IronRequiem/Reports/PrimaryModuleV02";
        const string Queue="Tools/IronRequiem/Requests/primary-module.txt",Key="IRON.PrimaryModule";static readonly DateTime LoadedAt=DateTime.UtcNow;static TestRunnerApi api;
        static PrimaryModuleAuthoring(){EditorApplication.update+=Tick;if(SessionState.GetBool(Key+".testing",false))EditorApplication.delayCall+=Register;}
        static bool Dirty()=>Enumerable.Range(0,SceneManager.sceneCount).Any(i=>SceneManager.GetSceneAt(i).isDirty);
        static void Register(){if(!api){api=ScriptableObject.CreateInstance<TestRunnerApi>();api.RegisterCallbacks(new Results());}}
        static void Tick(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||EditorApplication.isUpdating||SessionState.GetBool(Key+".testing",false))return;if(SessionState.GetBool(Key+".restore",false)&&EditorApplication.timeSinceStartup-SessionState.GetFloat(Key+".at",0)>3){SessionState.EraseBool(Key+".restore");if(!Dirty())EditorSceneManager.OpenScene(Lab);}if(!File.Exists(Queue))return;foreach(var path in new[]{"Assets/IronRequiem/Editor/PrimaryModuleAuthoring.cs","Assets/IronRequiem/Tests/PlayMode/PrimaryModuleTests.cs"})if(LoadedAt<File.GetLastWriteTimeUtc(path))return;string op=File.ReadAllText(Queue).Trim();File.Delete(Queue);Directory.CreateDirectory(Reports);try{if(op=="create"){Create();File.WriteAllText(Queue,"baseline");}else if(op=="baseline"||op=="test-balance")Run(op,new[]{"IronRequiem.Tests.PrimaryModuleTests.CommonEnemyTimeToKill","IronRequiem.Tests.PrimaryModuleTests.BigBotTimeToKill"});else if(op=="build"){Build();File.WriteAllText(Queue,"test-balance");}else if(op=="test-mount")Run(op,new[]{"IronRequiem.Tests.PrimaryModuleTests.MountAndPresentation"});else if(op=="tune-recharge"){var go=PrefabUtility.LoadPrefabContents(Weapon);try{go.GetComponent<WeaponController>().AmmoReloadDelay=.6f;Named(go,"Attachment").rotation=go.GetComponent<WeaponController>().WeaponMuzzle.rotation;Named(go,"Muzzle").rotation=go.GetComponent<WeaponController>().WeaponMuzzle.rotation;PrefabUtility.SaveAsPrefabAsset(go,Weapon);AssetDatabase.SaveAssets();}finally{PrefabUtility.UnloadPrefabContents(go);}File.WriteAllText(Queue,"test-sustain");}else if(op=="test-sustain")Run(op,new[]{"IronRequiem.Tests.PrimaryModuleTests.BigBotTimeToKill"});else if(op=="frame-mount"){var go=PrefabUtility.LoadPrefabContents(Weapon);try{var weapon=go.GetComponent<WeaponController>();var delta=Vector3.down*.03f;weapon.WeaponMuzzle.localPosition+=delta;Named(go,"PrimaryModuleVisual").localPosition+=delta;PrefabUtility.SaveAsPrefabAsset(go,Weapon);AssetDatabase.SaveAssets();File.WriteAllText(Reports+"/visible-geometry.txt",string.Join("\\n",go.GetComponentsInChildren<MeshRenderer>(true).Select(r=>r.name+" active="+r.gameObject.activeInHierarchy+" mesh="+AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh)+" vertices="+r.GetComponent<MeshFilter>().sharedMesh.vertexCount)));}finally{PrefabUtility.UnloadPrefabContents(go);}File.WriteAllText(Queue,"test-framing");}else if(op=="test-framing")Run(op,new[]{"IronRequiem.Tests.PrimaryModuleTests.MountAndPresentation","IronRequiem.Tests.PrimaryModuleTests.CommonEnemyTimeToKill"});else if(op=="verify")Verify();else throw new InvalidOperationException("Unknown primary module operation");}catch(Exception e){File.WriteAllText(Reports+"/error.txt",e.ToString());Debug.LogException(e);}}
        static void Variant(string source,string destination){if(File.Exists(destination))throw new InvalidOperationException("Preserve "+destination);var scene=EditorSceneManager.NewPreviewScene();try{var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(source),scene);go.name=Path.GetFileNameWithoutExtension(destination);PrefabUtility.SaveAsPrefabAsset(go,destination);}finally{EditorSceneManager.ClosePreviewScene(scene);}}
        static void Create(){if(Dirty())throw new InvalidOperationException("Preserving dirty user scene");Directory.CreateDirectory(Art);AssetDatabase.Refresh();Variant(CombatPolishAuthoring.Player,Player);if(File.Exists(Lab))throw new InvalidOperationException("Preserve existing lab");AssetDatabase.CopyAsset(CombatPolishAuthoring.Lab,Lab);var scene=EditorSceneManager.OpenScene(Lab);var old=Object.FindAnyObjectByType<PlayerCharacterController>().gameObject;var player=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Player),scene);player.transform.SetPositionAndRotation(old.transform.position,old.transform.rotation);Object.DestroyImmediate(old);string nav=Art+"/PrimaryModule_NavMesh.asset";AssetDatabase.CopyAsset(CombatPolishAuthoring.Art+"/CombatPolish_NavMesh.asset",nav);var surface=Object.FindAnyObjectByType<Unity.AI.Navigation.NavMeshSurface>();surface.RemoveData();surface.navMeshData=AssetDatabase.LoadAssetAtPath<UnityEngine.AI.NavMeshData>(nav);surface.AddData();EditorUtility.SetDirty(surface);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();}
        static void Run(string label,string[] names){if(Dirty())throw new InvalidOperationException("Preserving dirty user scene");Register();SessionState.SetBool(Key+".testing",true);SessionState.SetString(Key+".label",label);api.Execute(new ExecutionSettings(new Filter{testMode=TestMode.PlayMode,testNames=names}));}
        static Transform Named(GameObject go,string name)=>go.GetComponentsInChildren<Transform>(true).Single(t=>t.name==name);
        static void Build()
        {
            if(Dirty())throw new InvalidOperationException("Preserving dirty scene");string modelPath=Art+"/IR_PrimaryModule_v02.fbx";if(!File.Exists(modelPath))File.Copy("Tools/IronRequiem/Blender/Working/PrimaryModuleV02/IR_PrimaryModule_v02.fbx",modelPath);AssetDatabase.ImportAsset(modelPath,ImportAssetOptions.ForceSynchronousImport);var importer=(ModelImporter)AssetImporter.GetAtPath(modelPath);importer.materialImportMode=ModelImporterMaterialImportMode.None;importer.animationType=ModelImporterAnimationType.None;importer.importAnimation=false;importer.SaveAndReimport();
            if(!File.Exists(Weapon))Variant(CombatPolishAuthoring.Pistol,Weapon);if(!File.Exists(Projectile))Variant("Assets/IronRequiem/Prefabs/Weapons/Projectile_IR_Pistol.prefab",Projectile);
            var go=PrefabUtility.LoadPrefabContents(Projectile);try{go.GetComponent<ProjectileStandard>().Damage=11;PrefabUtility.SaveAsPrefabAsset(go,Projectile);}finally{PrefabUtility.UnloadPrefabContents(go);}
            string materialPath=Art+"/PrimaryModule_URP.mat";if(!File.Exists(materialPath))AssetDatabase.CopyAsset("Assets/IronRequiem/Art/Weapons/BasicPistolModule/PistolModule_URP.mat",materialPath);var material=AssetDatabase.LoadAssetAtPath<Material>(materialPath);material.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;material.EnableKeyword("_EMISSION");EditorUtility.SetDirty(material);
            go=PrefabUtility.LoadPrefabContents(Weapon);try{
                var weapon=go.GetComponent<WeaponController>();weapon.DelayBetweenShots=.2f;weapon.ProjectilePrefab=AssetDatabase.LoadAssetAtPath<GameObject>(Projectile).GetComponent<ProjectileBase>();weapon.MaxAmmo=32;weapon.AmmoReloadRate=32;weapon.AmmoReloadDelay=.6f;
                foreach(var name in new[]{"WeaponMesh_Pistol","PistolModule_1000_Equipped","RoboticWristCoupler"}){var oldVisual=go.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name==name);if(oldVisual){oldVisual.gameObject.SetActive(false);foreach(var t in oldVisual.GetComponentsInChildren<Transform>(true)){if(t.name=="Attachment")t.name="LegacyAttachment_1000";if(t.name=="Muzzle")t.name="LegacyMuzzle_1000";}}}
                weapon.WeaponMuzzle=Named(go,"GunMuzzle");weapon.WeaponMuzzle.localPosition=new Vector3(0,.094f,.410f);
                var old=go.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="PrimaryModuleVisual");if(old)Object.DestroyImmediate(old.gameObject);
                var visual=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(modelPath),go.scene);visual.name="PrimaryModuleVisual";visual.transform.SetParent(weapon.WeaponRoot.transform,false);foreach(var r in visual.GetComponentsInChildren<Renderer>(true))r.sharedMaterial=material;visual.transform.position+=weapon.WeaponMuzzle.position-Named(visual,"Muzzle").position;Named(visual,"Attachment").rotation=weapon.WeaponMuzzle.rotation;Named(visual,"Muzzle").rotation=weapon.WeaponMuzzle.rotation;
                var text=new System.Text.StringBuilder();foreach(var t in visual.GetComponentsInChildren<Transform>(true))text.AppendLine(t.name+" p="+t.position.ToString("F4")+" scale="+t.lossyScale+" rot="+t.eulerAngles);File.WriteAllText(Reports+"/model-mount.txt",text.ToString());PrefabUtility.SaveAsPrefabAsset(go,Weapon);
            }finally{PrefabUtility.UnloadPrefabContents(go);}
            go=PrefabUtility.LoadPrefabContents(Player);try{var manager=go.GetComponent<PlayerWeaponsManager>();var weapon=AssetDatabase.LoadAssetAtPath<GameObject>(Weapon).GetComponent<WeaponController>();for(int i=0;i<manager.StartingWeapons.Count;i++)if(manager.StartingWeapons[i].name=="Weapon_IR_Pistol_CombatPolish")manager.StartingWeapons[i]=weapon;var hands=new SerializedObject(go.GetComponent<ProtagonistHandsPresentation>());hands.FindProperty("pistolPrefab").objectReferenceValue=weapon;hands.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.SaveAsPrefabAsset(go,Player);}finally{PrefabUtility.UnloadPrefabContents(go);}AssetDatabase.SaveAssets();
        }
        static void Verify(){int missing=0;foreach(var path in new[]{Player,Weapon,Projectile}){var go=PrefabUtility.LoadPrefabContents(path);try{foreach(var t in go.GetComponentsInChildren<Transform>(true)){missing+=GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject);foreach(var component in t.GetComponents<Component>()){if(!component)continue;var data=new SerializedObject(component);var prop=data.GetIterator();while(prop.NextVisible(true))if(prop.propertyType==SerializedPropertyType.ObjectReference&&!prop.objectReferenceValue&&!prop.objectReferenceEntityIdValue.Equals(default(UnityEngine.EntityId)))throw new InvalidOperationException(path+" missing "+prop.propertyPath);}}}finally{PrefabUtility.UnloadPrefabContents(go);}}if(missing!=0)throw new InvalidOperationException("Missing scripts "+missing);File.WriteAllText(Reports+"/references.txt","3 variants: no missing scripts or serialized references");IronRequiemSetupTools.WriteAudit();}
        sealed class Results:IErrorCallbacks{public void RunStarted(ITestAdaptor t){}public void TestStarted(ITestAdaptor t){}public void TestFinished(ITestResultAdaptor t){}public void OnError(string message){SessionState.EraseBool(Key+".testing");File.WriteAllText(Reports+"/runner-error.txt",message);}public void RunFinished(ITestResultAdaptor result){if(!SessionState.GetBool(Key+".testing",false))return;SessionState.EraseBool(Key+".testing");string label=SessionState.GetString(Key+".label","");TestRunnerApi.SaveResultToFile(result,Reports+"/"+label+".xml");File.WriteAllText(Reports+"/status.txt",label+": "+result.ResultState+" passed="+result.PassCount+" failed="+result.FailCount);SessionState.SetBool(Key+".restore",true);SessionState.SetFloat(Key+".at",(float)EditorApplication.timeSinceStartup);}}
    }
